1	/**
2	 * @file vmap_tile.c
3	 * @brief vmap tile 模块。
4	 */
5	
6	#include "vmap_tile.h"
7	
8	#include "vmap_format.h"
9	#include <stddef.h>
10	#include <string.h>
11	
12	/**
13	 * @brief vmap tile ptr in range。
14	 */
15	static bool vmap_tile_ptr_in_range(const uint8_t * base, size_t sz,
16	    const uint8_t * p)
17	{
18	    if (!base || !p) {
19	        return false;
20	    }
21	    return p >= base && p < base + sz;
22	}
23	
24	/**
25	 * @brief vmap tile ptr add。
26	 */
27	static bool vmap_tile_ptr_add(const uint8_t * base, size_t sz,
28	    const uint8_t * p, size_t add, const uint8_t ** out)
29	{
30	    size_t used;
31	
32	    if (!out || !vmap_tile_ptr_in_range(base, sz, p)) {
33	        return false;
34	    }
35	    used = (size_t)(p - base);
36	    if (add > sz - used) {
37	        return false;
38	    }
39	    *out = p + add;
40	    return true;
41	}
42	
43	static inline uint16_t rd_u16(const uint8_t * p)
44	{
45	    return (uint16_t)(p[0] | (p[1] << 8));
46	}
47	
48	static inline uint32_t rd_u32(const uint8_t * p)
49	{
50	    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24));
51	}
52	
53	/**
54	 * @brief 重置瓦片结构。
55	 * @param tile 瓦片。
56	 */
57	void vmap_tile_reset(vmap_tile_t * tile)
58	{
59	    if (!tile) {
60	        return;
61	    }
62	    memset(tile, 0, sizeof(*tile));
63	    tile->extent = VMAP_EXTENT;
64	}
65	
66	/**
67	 * @brief 零拷贝解析瓦片缓冲。
68	 * @param tile 输出瓦片。
69	 * @param buf 原始字节。
70	 * @param sz 长度。
71	 * @return true 成功/有效，false 失败/无效。
72	 */
73	bool vmap_tile_parse_borrowed(vmap_tile_t * tile, const uint8_t * buf, size_t sz)
74	{
75	    vmap_tile_reset(tile);
76	
77	    if (!tile || !buf || sz < 20) {
78	        return false;
79	    }
80	
81	    if (!(buf[0] == VMAP_MAGIC0 && buf[1] == VMAP_MAGIC1
82	            && buf[2] == VMAP_MAGIC2 && buf[3] == VMAP_MAGIC3)) {
83	        return false;
84	    }
85	    /* v1 and v2 share the same header/layer layout. */
86	    if (buf[4] != 1 && buf[4] != VMAP_VERSION) {
87	        return false;
88	    }
89	
90	    tile->buf = buf;
91	    tile->extent = rd_u16(buf + 6);
92	    if (tile->extent == 0) {
93	        tile->extent = VMAP_EXTENT;
94	    }
95	    tile->tile_x = rd_u32(buf + 8);
96	    tile->tile_y = rd_u32(buf + 12);
97	    uint16_t layer_count = rd_u16(buf + 16);
98	
99	    const uint8_t * p = buf + 20;
100	
101	    for (uint16_t i = 0; i < layer_count && tile->num_layers < 8; i++) {
102	        uint8_t id;
103	        uint16_t feature_count;
104	        uint32_t layer_bytes;
105	        const uint8_t * hdr;
106	        const uint8_t * data;
107	        const uint8_t * next;
108	
109	        hdr = p;
110	        if (!vmap_tile_ptr_add(buf, sz, p, 8, &p)) {
111	            break;
112	        }
113	        id = hdr[0];
114	        feature_count = rd_u16(hdr + 2);
115	        layer_bytes = rd_u32(hdr + 4);
116	        data = p;
117	        if (!vmap_tile_ptr_add(buf, sz, data, layer_bytes, &next)) {
118	            break;
119	        }
120	        tile->layers[tile->num_layers].id = id;
121	        tile->layers[tile->num_layers].feature_count = feature_count;
122	        tile->layers[tile->num_layers].data = data;
123	        tile->layers[tile->num_layers].bytes = layer_bytes;
124	        tile->num_layers++;
125	        p = next;
126	    }
127	
128	    return true;
129	}
130	
131	/**
132	 * @brief 瓦片 extent（像素）。
133	 * @param tile 瓦片。
134	 */
135	uint16_t vmap_tile_extent(const vmap_tile_t * tile)
136	{
137	    return tile ? tile->extent : VMAP_EXTENT;
138	}
139	
140	/**
141	 * @brief 创建图层要素迭代器。
142	 */
143	vmap_feature_iter_t vmap_tile_layer_iter(const vmap_tile_t * tile, uint8_t layer_id)
144	{
145	    vmap_feature_iter_t it = { 0 };
146	    if (!tile) {
147	        return it;
148	    }
149	
150	    for (uint16_t i = 0; i < tile->num_layers; i++) {
151	        if (tile->layers[i].id == layer_id) {
152	            it.ptr = tile->layers[i].data;
153	            it.end = tile->layers[i].data + tile->layers[i].bytes;
154	            it.remaining = tile->layers[i].feature_count;
155	            break;
156	        }
157	    }
158	    return it;
159	}
160	
161	/**
162	 * @brief 迭代下一个要素。
163	 * @param it 迭代器。
164	 * @param out 输出要素。
165	 */
166	bool vmap_feature_iter_next(vmap_feature_iter_t * it, vmap_feature_t * out)
167	{
168	    if (!it || !out || it->remaining == 0 || !it->ptr || it->ptr + 4 > it->end) {
169	        return false;
170	    }
171	
172	    out->attr = it->ptr[0];
173	    out->flags = it->ptr[1];
174	    out->point_count = rd_u16(it->ptr + 2);
175	    const uint8_t * coords = it->ptr + 4;
176	    const uint8_t * nextp = coords + (size_t)out->point_count * 4;
177	
178	    out->coords = (const uint16_t *)coords;
179	    out->name_text = NULL;
180	    out->name_len = 0;
181	    if (out->flags & VMAP_FLAG_NAMED) {
182	        if (nextp + 1 > it->end) {
183	            it->remaining = 0;
184	            return false;
185	        }
186	        out->name_len = nextp[0];
187	        out->name_text = (const char *)(nextp + 1);
188	        nextp += 1u + out->name_len;
189	    }
190	
191	    if (nextp > it->end) {
192	        it->remaining = 0;
193	        return false;
194	    }
195	
196	    it->ptr = nextp;
197	    it->remaining--;
198	    return true;
199	}
200	
201	/**
202	 * @brief 创建标签迭代器。
203	 */
204	vmap_label_iter_t vmap_tile_label_iter(const vmap_tile_t * tile)
205	{
206	    vmap_label_iter_t it = { 0 };
207	    if (!tile) {
208	        return it;
209	    }
210	
211	    for (uint16_t i = 0; i < tile->num_layers; i++) {
212	        if (tile->layers[i].id == VMAP_LAYER_LABEL) {
213	            it.ptr = tile->layers[i].data;
214	            it.end = tile->layers[i].data + tile->layers[i].bytes;
215	            it.remaining = tile->layers[i].feature_count;
216	            break;
217	        }
218	    }
219	    return it;
220	}
221	
222	/**
223	 * @brief 迭代下一个标签。
224	 */
225	bool vmap_label_iter_next(vmap_label_iter_t * it, vmap_label_t * out)
226	{
227	    if (!it || !out || it->remaining == 0 || !it->ptr || it->ptr + 8 > it->end) {
228	        return false;
229	    }
230	
231	    out->kind = it->ptr[0];
232	    out->priority = it->ptr[1];
233	    out->x = (int32_t)rd_u16(it->ptr + 2);
234	    out->y = (int32_t)rd_u16(it->ptr + 4);
235	    out->len = it->ptr[6];
236	    out->text = (const char *)(it->ptr + 8);
237	
238	    const uint8_t * nextp = it->ptr + 8 + out->len;
239	    if (nextp > it->end) {
240	        it->remaining = 0;
241	        return false;
242	    }
243	
244	    it->ptr = nextp;
245	    it->remaining--;
246	    return true;
247	}
