16	#include "vmap_style.h"   /* 风格闸门：切主题要让"已烘焙的瓦片位图"过期 */
17	#include "lvgl/lvgl.h"
18	#include <myvendor_mtp_lfs.h>
19	#include "myvendor_watchdog.h"
20	#include <errno.h>
