26	
27	#ifndef M_PI
28	#define M_PI 3.14159265358979323846
29	#endif
30	
31	/* Number of region packs kept open simultaneously. A single on-screen view can
32	 * straddle several grid cells (especially when zoomed out or when the current
33	 * position sits near a cell boundary), so tiles must be servable from more than
34	 * just the active region. */
35	#define VMAP_REG_SLOTS 4
36	
37	struct regional_entry {
38	    uint8_t z;
39	    uint16_t x;
40	    uint16_t y;
41	    uint32_t offset;
42	    uint32_t size;
43	};
44	
45	/* One resident region pack: its tile table plus an open file handle. */
46	struct reg_slot {
47	    bool used;
48	    vmap_cell_id_t region_id;
49	    struct regional_entry * entries;
50	    uint16_t entry_count;
51	    uint32_t graph_off;
52	    uint32_t graph_sz;
53	    FILE * fp;
54	    const uint8_t * ram;
55	    uint32_t ram_sz;
56	    uint32_t lru;
57	};
58	
59	struct vmap_tile_cache {
60	    char tile_dir[64];
61	    int zoom;
62	    bool packed;
63	    uint16_t city_id;
64	    vmap_tile_index_t * index;
65	    FILE * pack_fp;
66	    int pack_zoom;
67	    uint16_t pack_id;
68	    char pack_path[64];
69	    uint8_t * staging;
70	    size_t staging_cap;
71	    bool has_reg_pack;
72	    vmap_cell_id_t region_id;
73	    uint32_t region_graph_off;
74	    uint32_t region_graph_sz;
75	    struct reg_slot slots[VMAP_REG_SLOTS];
76	    uint32_t lru_clock;
77	    /** 位图是按哪份 vmap 风格烘焙的（见 vmap_tile_cache_get 的风格闸门）。 */
78	    uint8_t style_id;
79	};
80	
81	static inline uint16_t rd_u16(const uint8_t * p)
82	{
83	    return (uint16_t)(p[0] | (p[1] << 8));
84	}
85	
86	static inline uint32_t rd_u32(const uint8_t * p)
87	{
88	    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24));
89	}
90	
91	static void slot_clear(struct reg_slot * s)
92	{
93	    if (!s) {
94	        return;
95	    }
96	    if (s->ram) {
97	        vmap_vpk_heap_unpin(s->region_id);
98	        s->ram = NULL;
99	    }
100	    s->ram_sz = 0;
101	    if (s->fp) {
102	        fclose(s->fp);
103	        s->fp = NULL;
104	    }
105	    if (s->entries) {
106	        vmap_free(s->entries);
107	        s->entries = NULL;
108	    }
109	    s->entry_count = 0;
110	    s->graph_off = 0;
111	    s->graph_sz = 0;
112	    s->region_id = VMAP_CELL_NONE;
113	    s->used = false;
114	    s->lru = 0;
115	}
116	
117	static void regional_clear(vmap_tile_cache_t * cache)
118	{
119	    int i;
120	
121	    if (!cache) {
122	        return;
123	    }
124	    for (i = 0; i < VMAP_REG_SLOTS; i++) {
125	        slot_clear(&cache->slots[i]);
126	    }
127	    cache->region_graph_off = 0;
128	    cache->region_graph_sz = 0;
129	    cache->region_id = VMAP_CELL_NONE;
130	    cache->has_reg_pack = false;
131	}
132	
133	/* Close file handles for all resident region packs but keep their tile tables
134	 * so they can be reopened cheaply once flash access resumes (MTP quiesce). */
135	static void slots_close_fps(vmap_tile_cache_t * cache)
136	{
137	    int i;
138	
139	    if (!cache) {
140	        return;
141	    }
142	    for (i = 0; i < VMAP_REG_SLOTS; i++) {
143	        if (cache->slots[i].fp) {
144	            fclose(cache->slots[i].fp);
145	            cache->slots[i].fp = NULL;
146	        }
147	    }
148	}
149	
150	/* Web-Mercator tile center back to WGS84 lon/lat, matching the packer's
151	 * per-tile cell assignment so a tile always resolves to the region that
152	 * actually contains it. */
153	static void tile_center_lonlat(int z, int x, int y, double * lon, double * lat)
154	{
155	    double n = (double)(1u << (unsigned)z);
156	    double t = M_PI * (1.0 - 2.0 * ((double)y + 0.5) / n);
157	
158	    *lon = ((double)x + 0.5) / n * 360.0 - 180.0;
159	    *lat = 180.0 / M_PI * atan(sinh(t));
160	}
161	
162	static uint16_t cell_arena_key(vmap_cell_id_t id)
163	{
164	    if (id == VMAP_CELL_NONE) {
165	        return 0xffffu;
166	    }
167	    return (uint16_t)(id ^ (id >> 16));
168	}
169	
170	/* Arena key: owning grid cell for this tile (tile-center rule, pack_map). */
171	static vmap_cell_id_t tile_cache_region(vmap_tile_cache_t * cache, int z, int x, int y)
172	{
173	    double lon;
174	    double lat;
175	    vmap_cell_id_t rid;
176	
177	    if (!cache) {
178	        return VMAP_CELL_NONE;
179	    }
180	    if (!vmap_map_catalog_is_regional()) {
181	        return cache->city_id;
182	    }
183	    tile_center_lonlat(z, x, y, &lon, &lat);
184	    if (!vmap_map_catalog_find_region(lon, lat, &rid)) {
185	        return cache->region_id;
186	    }
187	    return rid;
188	}
189	
190	static bool tile_blob_magic_ok(const uint8_t * data, uint32_t size)
191	{
192	    if (!data || size < 5) {
193	        return false;
194	    }
195	    if (!(data[0] == VMAP_MAGIC0 && data[1] == VMAP_MAGIC1
196	            && data[2] == VMAP_MAGIC2 && data[3] == VMAP_MAGIC3)) {
197	        return false;
198	    }
199	    return data[4] == 1 || data[4] == VMAP_VERSION;
200	}
201	
202	static bool staging_ensure(vmap_tile_cache_t * cache, uint32_t need)
203	{
204	    uint8_t * p;
205	    size_t cap;
206	
207	    if (!cache || need == 0 || need > VMAP_TILE_BYTES_MAX) {
208	        return false;
209	    }
210	    if (cache->staging && need <= cache->staging_cap) {
211	        return true;
212	    }
213	    cap = (size_t)need;
214	    if (cap < (size_t)VMAP_STAGING_CAP) {
215	        cap = (size_t)VMAP_STAGING_CAP;
216	    }
217	    p = (uint8_t *)vmap_malloc(cap);
218	    if (!p) {
219	        return false;
220	    }
221	    if (cache->staging) {
222	        vmap_free(cache->staging);
223	    }
224	    cache->staging = p;
225	    cache->staging_cap = cap;
226	    return true;
227	}
228	
229	static void close_pack(vmap_tile_cache_t * cache)
230	{
231	    if (!cache) {
232	        return;
233	    }
234	    if (cache->pack_fp) {
235	        fclose(cache->pack_fp);
236	        cache->pack_fp = NULL;
237	    }
238	    cache->pack_zoom = -1;
239	    cache->pack_id = 0xffff;
240	    cache->pack_path[0] = '\0';
241	}
242	
243	static bool open_pack_path(vmap_tile_cache_t * cache, const char * path,
244	    uint16_t pack_id)
245	{
246	    if (cache->pack_fp && cache->pack_id == pack_id
247	        && strcmp(cache->pack_path, path) == 0) {
248	        return true;
249	    }
250	
251	    close_pack(cache);
252	    lv_strlcpy(cache->pack_path, path, sizeof(cache->pack_path));
253	    cache->pack_fp = fopen(path, "rb");
254	    if (!cache->pack_fp) {
255	        return false;
256	    }
257	    cache->pack_zoom = 0;
258	    cache->pack_id = pack_id;
259	    return true;
260	}
261	
262	static bool open_pack(vmap_tile_cache_t * cache, uint16_t pack_id)
263	{
264	    char path[72];
265	
266	    lv_snprintf(path, sizeof(path), "%s/p%03d.%s",
267	        cache->tile_dir, (int)pack_id, VMAP_SHARD_EXT);
268	    return open_pack_path(cache, path, pack_id);
269	}
270	
271	static bool regional_find_in(const struct reg_slot * slot, int z, int x, int y,
272	    const struct regional_entry ** out)
273	{
274	    int lo;
275	    int hi;
276	
277	    if (!slot || !slot->entries || slot->entry_count == 0) {
278	        return false;
279	    }
280	
281	    lo = 0;
282	    hi = (int)slot->entry_count - 1;
283	    while (lo <= hi) {
284	        int mid = (lo + hi) / 2;
285	        const struct regional_entry * e = &slot->entries[mid];
286	
287	        if (e->z < (uint8_t)z
288	            || (e->z == (uint8_t)z && e->y < (uint16_t)y)
289	            || (e->z == (uint8_t)z && e->y == (uint16_t)y
290	                && e->x < (uint16_t)x)) {
291	            lo = mid + 1;
292	        } else if (e->z > (uint8_t)z
293	            || (e->z == (uint8_t)z && e->y > (uint16_t)y)
294	            || (e->z == (uint8_t)z && e->y == (uint16_t)y
295	                && e->x > (uint16_t)x)) {
296	            hi = mid - 1;
297	        } else {
298	            if (out) {
299	                *out = e;
300	            }
301	            return true;
302	        }
303	    }
304	    return false;
305	}
