307	static void resolve_region_vpk(char * buf, size_t sz,
308	    const char * dir, vmap_cell_id_t region_id)
309	{
310	    vmap_grid_vpk_path(buf, sz, dir, VMAP_CELL_IX(region_id),
311	        VMAP_CELL_IY(region_id));
312	}
313	
314	static bool fill_entries(struct reg_slot * victim, const uint8_t * hdr,
315	    const uint8_t * recs, uint32_t recs_bytes)
316	{
317	    uint32_t tile_count;
318	    uint32_t rec_sz;
319	    uint32_t k;
320	
321	    if (!(hdr[0] == VMAP_REG_PACK_INDEX_MAGIC0
322	            && hdr[1] == VMAP_REG_PACK_INDEX_MAGIC1
323	            && hdr[2] == VMAP_REG_PACK_INDEX_MAGIC2
324	            && hdr[3] == VMAP_REG_PACK_INDEX_MAGIC3)) {
325	        return false;
326	    }
327	    if (hdr[4] != VMAP_REG_PACK_INDEX_VERSION
328	            && hdr[4] != VMAP_REG_PACK_INDEX_VERSION2) {
329	        return false;
330	    }
331	    tile_count = rd_u32(hdr + 8);
332	    if (tile_count == 0 || tile_count > 4096u) {
333	        return false;
334	    }
335	    rec_sz = (hdr[4] == VMAP_REG_PACK_INDEX_VERSION2)
336	        ? (uint32_t)VMAP_REG_PACK_TILE_REC_SIZE_V2
337	        : (uint32_t)VMAP_REG_PACK_TILE_REC_SIZE;
338	    if (recs_bytes < tile_count * rec_sz) {
339	        return false;
340	    }
341	    victim->entries = (struct regional_entry *)vmap_malloc(
342	        (size_t)tile_count * sizeof(*victim->entries));
343	    if (!victim->entries) {
344	        return false;
345	    }
346	    for (k = 0; k < tile_count; k++) {
347	        const uint8_t * rec = recs + k * rec_sz;
348	        struct regional_entry * e = &victim->entries[k];
349	
350	        e->z = rec[0];
351	        e->x = rd_u16(rec + 2);
352	        e->y = rd_u16(rec + 4);
353	        e->offset = rd_u32(rec + 8);
354	        e->size = (hdr[4] == VMAP_REG_PACK_INDEX_VERSION2)
355	            ? rd_u32(rec + 12) : rd_u16(rec + 12);
356	        if (e->size > VMAP_TILE_BYTES_MAX) {
357	            vmap_free(victim->entries);
358	            victim->entries = NULL;
359	            return false;
360	        }
361	    }
362	    victim->entry_count = (uint16_t)tile_count;
363	    victim->graph_off = rd_u32(hdr + 12);
364	    victim->graph_sz = rd_u32(hdr + 16);
365	    return true;
366	}
367	
368	static bool slot_bind_ram(struct reg_slot * victim, vmap_cell_id_t region_id,
369	    const uint8_t * ram, uint32_t ram_sz)
370	{
371	    if (!ram || ram_sz < VMAP_VPK_HDR_SIZE + VMAP_REG_PACK_INDEX_HDR_SIZE) {
372	        return false;
373	    }
374	    if (!(ram[0] == VMAP_PACK_MAGIC0 && ram[1] == VMAP_PACK_MAGIC1
375	            && ram[2] == VMAP_PACK_MAGIC2 && ram[3] == VMAP_PACK_MAGIC3)) {
376	        return false;
377	    }
378	    if (!fill_entries(victim, ram + VMAP_VPK_HDR_SIZE,
379	            ram + VMAP_VPK_HDR_SIZE + VMAP_REG_PACK_INDEX_HDR_SIZE,
380	            ram_sz - VMAP_VPK_HDR_SIZE - VMAP_REG_PACK_INDEX_HDR_SIZE)) {
381	        return false;
382	    }
383	    victim->ram = NULL;
384	    victim->ram_sz = 0;
385	    victim->fp = NULL;
386	    victim->region_id = region_id;
387	    victim->used = true;
388	    return true;
389	}
390	
391	/* Make a region pack resident in a slot (reusing it if already loaded, else
392	 * evicting the least-recently-used non-active slot). Returns the slot. */
393	static struct reg_slot * slot_load(vmap_tile_cache_t * cache, vmap_cell_id_t region_id)
394	{
395	    char path[VMAP_GRID_PATH_MAX];
396	    struct reg_slot * victim = NULL;
397	    const uint8_t * ram = NULL;
398	    uint32_t ram_sz = 0;
399	    int i;
400	
401	    if (!cache || cache->tile_dir[0] == '\0') {
402	        return NULL;
403	    }
404	
405	    for (i = 0; i < VMAP_REG_SLOTS; i++) {
406	        struct reg_slot * s = &cache->slots[i];
407	
408	        if (!s->used || s->region_id != region_id) {
409	            continue;
410	        }
411	        s->lru = ++cache->lru_clock;
412	        vmap_vpk_heap_touch(region_id);
413	        return s;
414	    }
415	
416	    for (i = 0; i < VMAP_REG_SLOTS; i++) {
417	        struct reg_slot * s = &cache->slots[i];
418	
419	        if (!s->used) {
420	            victim = s;
421	            break;
422	        }
423	        if (s->region_id == cache->region_id) {
424	            continue;
425	        }
426	        if (!victim || s->lru < victim->lru) {
427	            victim = s;
428	        }
429	    }
430	    if (!victim) {
431	        victim = &cache->slots[0];
432	    }
433	    slot_clear(victim);
434	
435	    resolve_region_vpk(path, sizeof(path), cache->tile_dir, region_id);
436	    if (!vmap_vpk_heap_pin(region_id, path, &ram, &ram_sz)) {
437	        static vmap_cell_id_t last_fail = VMAP_CELL_NONE;
438	
439	        if (last_fail != region_id) {
440	            last_fail = region_id;
441	            syslog(LOG_WARNING, "[vmap] vpk pin fail cell=%u",
442	                (unsigned)region_id);
443	        }
444	        return NULL;
445	    }
446	    if (!slot_bind_ram(victim, region_id, ram, ram_sz)) {
447	        vmap_vpk_heap_unpin(region_id);
448	        slot_clear(victim);
449	        return NULL;
450	    }
451	    /* 解析完索引就 unpin：文件仍留在 heap，refs=0 才能给邻格腾地方。 */
452	    vmap_vpk_heap_unpin(region_id);
453	    victim->lru = ++cache->lru_clock;
454	    return victim;
455	}
