457	static bool load_regional_pack(vmap_tile_cache_t * cache, vmap_cell_id_t region_id)
458	{
459	    struct reg_slot * s;
460	    uint16_t arena_key;
461	
462	    if (!cache || cache->tile_dir[0] == '\0' || region_id == VMAP_CELL_NONE) {
463	        return false;
464	    }
465	
466	    s = slot_load(cache, region_id);
467	    if (!s) {
468	        return false;
469	    }
470	
471	    cache->region_id = region_id;
472	    cache->region_graph_off = s->graph_off;
473	    cache->region_graph_sz = s->graph_sz;
474	    cache->has_reg_pack = true;
475	    cache->packed = true;
476	
477	    arena_key = cell_arena_key(region_id);
478	    if (cache->city_id != arena_key) {
479	        cache->city_id = arena_key;
480	        vmap_cache_set_city_id(arena_key);
481	    }
482	    vmap_map_catalog_set_active_region(region_id);
483	    return true;
484	}
