661	/* 1=读到瓦片，0=包里没有，-1=瞬时 I/O（SD/句柄），下次再试，勿记 MISSING。 */
662	static int load_from_flash(vmap_tile_cache_t * cache, int z, int x, int y,
663	    uint32_t * out_size)
664	{
665	    const struct regional_entry * re = NULL;
666	    vmap_tile_ref_t ref;
667	
668	    if (!cache || myvendor_mtp_lfs_quiesce()) {
669	        return -1;
670	    }
671	
672	    /* Grid: lonN/latN/x_y.vpk. Look up the cell that owns this tile's
673	     * center (same rule as pack_map.py). Do not fall through to VIDX / .vt. */
674	    if (vmap_map_catalog_is_regional()) {
675	        struct reg_slot * slot = NULL;
676	        double lon;
677	        double lat;
678	        vmap_cell_id_t rid;
679	
680	        if (cache->has_reg_pack) {
681	            slot = slot_load(cache, cache->region_id);
682	            if (slot && !regional_find_in(slot, z, x, y, &re)) {
683	                slot = NULL;
684	            }
685	        }
686	        if (!slot) {
687	            tile_center_lonlat(z, x, y, &lon, &lat);
688	            if (!vmap_map_catalog_find_region(lon, lat, &rid)) {
689	                return 0;
690	            }
691	            slot = slot_load(cache, rid);
692	            if (!slot) {
693	                return -1;
694	            }
695	            if (!regional_find_in(slot, z, x, y, &re)) {
696	                return 0;
697	            }
698	        }
699	        if (!re || !slot || !staging_ensure(cache, re->size)) {
700	            return -1;
701	        }
702	        {
703	            char path[VMAP_GRID_PATH_MAX];
704	
705	            resolve_region_vpk(path, sizeof(path), cache->tile_dir,
706	                slot->region_id);
707	            if (!vmap_vpk_heap_copy(slot->region_id, path,
708	                    VMAP_VPK_HDR_SIZE + re->offset, cache->staging, re->size)) {
709	                return -1;
710	            }
711	        }
712	        if (out_size) {
713	            *out_size = re->size;
714	        }
715	        return 1;
716	    }
717	
718	    if (cache->packed && vmap_tile_index_is_loaded(cache->index)) {
719	        if (!vmap_tile_index_find(cache->index, z, x, y, &ref)) {
720	            return 0;
721	        }
722	        if (!staging_ensure(cache, ref.size) || !open_pack(cache, ref.pack_id)) {
723	            return -1;
724	        }
725	        if (fseek(cache->pack_fp, (long)(VMAP_VPK_HDR_SIZE + ref.offset),
726	                SEEK_SET) != 0) {
727	            return -1;
728	        }
729	        if (fread(cache->staging, 1, ref.size, cache->pack_fp) != (size_t)ref.size) {
730	            return -1;
731	        }
732	        if (out_size) {
733	            *out_size = ref.size;
734	        }
735	        return 1;
736	    }
737	
738	    char path[64];
739	    FILE * fp;
740	    long sz;
741	
742	    lv_snprintf(path, sizeof(path), "%s/%d/%d/%d.vt", cache->tile_dir, z, x, y);
743	    fp = fopen(path, "rb");
744	    if (!fp) {
745	        return (errno == ENOENT) ? 0 : -1;
746	    }
747	    fseek(fp, 0, SEEK_END);
748	    sz = ftell(fp);
749	    fseek(fp, 0, SEEK_SET);
750	    if (sz < 20 || (unsigned long)sz > (unsigned long)VMAP_TILE_BYTES_MAX) {
751	        fclose(fp);
752	        return 0;
753	    }
754	    if (!staging_ensure(cache, (uint32_t)sz)) {
755	        fclose(fp);
756	        return -1;
757	    }
758	    if (fread(cache->staging, 1, (size_t)sz, fp) != (size_t)sz) {
759	        fclose(fp);
760	        return -1;
761	    }
762	    fclose(fp);
763	    if (out_size) {
764	        *out_size = (uint32_t)sz;
765	    }
766	    return 1;
767	}
