810	/**
811	 * @brief vmap tile cache get。
812	 * @return 请求的值。
813	 */
814	bool vmap_tile_cache_get(vmap_tile_cache_t * cache, int z, int x, int y,
815	    vmap_tile_t * out_tile)
816	{
817	    vmap_cache_blob_t blob;
818	    vmap_cell_id_t cell;
819	    uint16_t rid;
820	
821	    if (!cache || !out_tile || cache->tile_dir[0] == '\0' || !cache->staging) {
822	        return false;
823	    }
824	
825	    /*
826	     * 风格闸门（2026-09-27）：缓存键里**没有**风格，位图是按烘焙时的风格存的 ⇒ 切主题
827	     * （vmap 风格）后必须整批作废，否则只有"恰好被重绘过"的瓦片换了色 —— 实测症状就是
828	     * 夜间主题下白色轨迹线压在浅色地图上（用户报的"REC 线没颜色 / 里程碑白圈白字"）。
829	     * 丢位图的配方与 load 路径一致：清槽 + 丢 arena；包/索引/目录都不动（那是换地图的事）。
830	     */
831	    if (cache->style_id != (uint8_t)vmap_style_get_id()) {
832	        cache->style_id = (uint8_t)vmap_style_get_id();
833	        regional_clear(cache);
834	        vmap_cache_arena_reset();
835	        syslog(LOG_NOTICE, "[vmap] style changed -> tile cache dropped (%s)\n",
836	               vmap_style_current()->name);
837	    }
838	
839	    if (z != cache->zoom) {
840	        vmap_tile_cache_set_zoom(cache, z);
841	    }
842	
843	    cell = tile_cache_region(cache, z, x, y);
844	    rid = vmap_map_catalog_is_regional() ? cell_arena_key(cell) : (uint16_t)cell;
845	
846	    if (vmap_cache_lookup(rid, z, x, y, &blob)) {
847	        if (blob.flags & VMAP_CACHE_FLAG_MISSING) {
848	            return false;
849	        }
850	        if (!tile_blob_magic_ok(blob.data, blob.size)
851	            || !vmap_tile_parse_borrowed(out_tile, blob.data, blob.size)) {
852	            vmap_cache_invalidate(rid, z, x, y);
853	        } else {
854	            return true;
855	        }
856	    }
857	
858	    uint32_t size = 0;
859	    int loaded = load_from_flash(cache, z, x, y, &size);
860	
861	    if (loaded < 0) {
862	        return false;
863	    }
864	    if (loaded == 0) {
865	        vmap_cache_insert_missing(rid, z, x, y);
866	        return false;
867	    }
868	    myvendor_watchdog_busy_pump();
869	
870	    if (!tile_blob_magic_ok(cache->staging, size)) {
871	        vmap_cache_insert_missing(rid, z, x, y);
872	        return false;
873	    }
874	
875	    if (vmap_cache_insert(rid, z, x, y, cache->staging, size) != 0) {
876	        return vmap_tile_parse_borrowed(out_tile, cache->staging, size);
877	    }
878	
879	    if (vmap_cache_lookup(rid, z, x, y, &blob)
880	        && !(blob.flags & VMAP_CACHE_FLAG_MISSING)
881	        && tile_blob_magic_ok(blob.data, blob.size)) {
882	        return vmap_tile_parse_borrowed(out_tile, blob.data, blob.size);
883	    }
884	
885	    return false;
886	}
