1	/**
2	 * @file vmap_vpk_heap.c
3	 * @brief First-fit PSRAM heap for whole cell vpk files (LRU unused eviction).
4	 */
5	
6	#include "vmap_vpk_heap.h"
7	
8	#include "vmap_config.h"
9	#include "board_malloc.h"
10	#include <myvendor_mtp_lfs.h>
11	#include "myvendor_watchdog.h"
12	#include <errno.h>
13	#include <fcntl.h>
14	#include <pthread.h>
15	#include <string.h>
16	#include <sys/stat.h>
17	#include <syslog.h>
18	#include <unistd.h>
19	
20	#ifndef CONFIG_MYVENDOR_VMAP_VPK_HEAP_KB
21	#  define CONFIG_MYVENDOR_VMAP_VPK_HEAP_KB 1024
22	#endif
23	
24	#define VPK_HEAP_BYTES ((size_t)CONFIG_MYVENDOR_VMAP_VPK_HEAP_KB * 1024u)
25	#define VPK_HEAP_ALIGN 8u
26	#define VPK_HEAP_MAX_BLOCKS 24
27	#define VPK_HEAP_MIN_SPLIT 32u
28	/* Match SD CMD18 max (8 x 512 B). FAT direct-I/O of a 32 KiB cluster into
29	 * PSRAM was aborting mid-file (stat size ok, fread short). Bounce in .bss. */
30	#define VPK_HEAP_IO_CHUNK  4096u
31	#define VPK_HEAP_IO_TRIES  3
32	
33	static uint8_t g_vpk_bounce[VPK_HEAP_IO_CHUNK] __attribute__((aligned(32)));
34	
35	static bool io_read_fd(int fd, void * dst, uint32_t len)
36	{
37	    uint8_t * p = (uint8_t *)dst;
38	    uint32_t got = 0;
39	
40	    while (got < len) {
41	        uint32_t chunk = len - got;
42	        ssize_t n;
43	
44	        if (chunk > VPK_HEAP_IO_CHUNK) {
45	            chunk = VPK_HEAP_IO_CHUNK;
46	        }
47	        n = read(fd, g_vpk_bounce, (size_t)chunk);
48	        if (n <= 0) {
49	            return false;
50	        }
51	        memcpy(p + got, g_vpk_bounce, (size_t)n);
52	        got += (uint32_t)n;
53	        myvendor_watchdog_busy_pump();
54	    }
55	    return true;
56	}
57	
58	typedef struct {
59	    vmap_cell_id_t id;
60	    uint32_t off;
61	    uint32_t size;
62	    uint32_t file_sz;
63	    uint32_t lru;
64	    int refs;
65	} vpk_block_t;
66	
67	static uint8_t * g_heap;
68	static size_t g_heap_bytes;
69	static vpk_block_t g_blk[VPK_HEAP_MAX_BLOCKS];
70	static uint32_t g_n;
71	static uint32_t g_clock;
72	static bool g_ready;
73	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
74	
75	static void init_unlocked(void)
76	{
77	    if (g_ready) {
78	        return;
79	    }
80	    g_heap_bytes = VPK_HEAP_BYTES;
81	    if (g_heap_bytes < 64u * 1024u) {
82	        return;
83	    }
84	    g_heap = (uint8_t *)board_malloc_psram(g_heap_bytes);
85	    if (!g_heap) {
86	        syslog(LOG_ERR, "[vmap] vpk heap alloc %u KiB failed\n",
87	            (unsigned)(g_heap_bytes / 1024u));
88	        return;
89	    }
90	    g_n = 1;
91	    g_blk[0].id = VMAP_CELL_NONE;
92	    g_blk[0].off = 0;
93	    g_blk[0].size = (uint32_t)g_heap_bytes;
94	    g_blk[0].file_sz = 0;
95	    g_blk[0].lru = 0;
96	    g_blk[0].refs = 0;
97	    g_clock = 0;
98	    g_ready = true;
99	    syslog(LOG_NOTICE, "[vmap] vpk heap %u KiB psram\n",
100	        (unsigned)(g_heap_bytes / 1024u));
101	}
102	
103	static uint32_t align_up(uint32_t n)
104	{
105	    return (n + (VPK_HEAP_ALIGN - 1u)) & ~(VPK_HEAP_ALIGN - 1u);
106	}
107	
108	static int find_id(vmap_cell_id_t id)
109	{
110	    uint32_t i;
111	
112	    if (id == VMAP_CELL_NONE) {
113	        return -1;
114	    }
115	    for (i = 0; i < g_n; i++) {
116	        if (g_blk[i].id == id) {
117	            return (int)i;
118	        }
119	    }
120	    return -1;
121	}
122	
123	static void coalesce(void)
124	{
125	    uint32_t i = 0;
126	
127	    while (i + 1u < g_n) {
128	        if (g_blk[i].id == VMAP_CELL_NONE
129	                && g_blk[i + 1u].id == VMAP_CELL_NONE) {
130	            g_blk[i].size += g_blk[i + 1u].size;
131	            memmove(&g_blk[i + 1u], &g_blk[i + 2u],
132	                (size_t)(g_n - i - 2u) * sizeof(g_blk[0]));
133	            g_n--;
134	        } else {
135	            i++;
136	        }
137	    }
138	}
139	
140	static bool evict_one(void)
141	{
142	    int best = -1;
143	    uint32_t i;
144	
145	    for (i = 0; i < g_n; i++) {
146	        if (g_blk[i].id == VMAP_CELL_NONE || g_blk[i].refs > 0) {
147	            continue;
148	        }
149	        if (best < 0 || g_blk[i].lru < g_blk[best].lru) {
150	            best = (int)i;
151	        }
152	    }
153	    if (best < 0) {
154	        return false;
155	    }
156	    g_blk[best].id = VMAP_CELL_NONE;
157	    g_blk[best].refs = 0;
158	    g_blk[best].file_sz = 0;
159	    g_blk[best].lru = 0;
160	    coalesce();
161	    return true;
162	}
163	
164	static int alloc_need(uint32_t need)
165	{
166	    uint32_t i;
167	
168	    for (i = 0; i < g_n; i++) {
169	        uint32_t leftover;
170	
171	        if (g_blk[i].id != VMAP_CELL_NONE || g_blk[i].size < need) {
172	            continue;
173	        }
174	        leftover = g_blk[i].size - need;
175	        if (leftover >= VPK_HEAP_MIN_SPLIT && g_n < VPK_HEAP_MAX_BLOCKS) {
176	            memmove(&g_blk[i + 2u], &g_blk[i + 1u],
177	                (size_t)(g_n - i - 1u) * sizeof(g_blk[0]));
178	            g_n++;
179	            g_blk[i + 1u].id = VMAP_CELL_NONE;
180	            g_blk[i + 1u].off = g_blk[i].off + need;
181	            g_blk[i + 1u].size = leftover;
182	            g_blk[i + 1u].file_sz = 0;
183	            g_blk[i + 1u].lru = 0;
184	            g_blk[i + 1u].refs = 0;
185	            g_blk[i].size = need;
186	        }
187	        return (int)i;
188	    }
189	    return -1;
190	}
191	
192	static bool file_copy(const char * path, uint32_t off, void * dst, uint32_t len)
193	{
194	    int fd;
195	    bool ok;
196	
197	    if (!path || !dst || len == 0) {
198	        return false;
199	    }
200	    fd = open(path, O_RDONLY);
201	    if (fd < 0) {
202	        return false;
203	    }
204	    ok = lseek(fd, (off_t)off, SEEK_SET) == (off_t)off
205	        && io_read_fd(fd, dst, len);
206	    close(fd);
207	    return ok;
208	}
209	
210	static bool load_into(int idx, const char * path, uint32_t file_sz)
211	{
212	    int try;
213	    int fd;
214	    bool ok = false;
215	
216	    for (try = 0; try < VPK_HEAP_IO_TRIES; try++) {
217	        fd = open(path, O_RDONLY);
218	        if (fd < 0) {
219	            syslog(LOG_WARNING, "[vmap] vpk open fail %s errno=%d",
220	                path, errno);
221	            continue;
222	        }
223	        ok = io_read_fd(fd, g_heap + g_blk[idx].off, file_sz);
224	        if (!ok) {
225	            syslog(LOG_WARNING, "[vmap] vpk read fail %s errno=%d try=%d",
226	                path, errno, try);
227	        }
228	        close(fd);
229	        if (ok) {
230	            return true;
231	        }
232	    }
233	    return false;
234	}
235	
236	static bool ensure_locked(vmap_cell_id_t id, const char * path, int * out_idx)
237	{
238	    struct stat st;
239	    uint32_t file_sz;
240	    uint32_t need;
241	    int idx;
242	
243	    idx = find_id(id);
244	    if (idx >= 0) {
245	        g_blk[idx].lru = ++g_clock;
246	        *out_idx = idx;
247	        return true;
248	    }
249	    if (!path || myvendor_mtp_lfs_quiesce()) {
250	        return false;
251	    }
252	    if (stat(path, &st) != 0 || st.st_size <= 0) {
253	        return false;
254	    }
255	    file_sz = (uint32_t)st.st_size;
256	    need = align_up(file_sz);
257	    if (need > g_heap_bytes || need == 0) {
258	        syslog(LOG_WARNING, "[vmap] vpk too big %u KiB (heap %u)",
259	            (unsigned)((file_sz + 1023u) / 1024u),
260	            (unsigned)(g_heap_bytes / 1024u));
261	        return false;
262	    }
263	    idx = alloc_need(need);
264	    while (idx < 0) {
265	        if (!evict_one()) {
266	            return false;
267	        }
268	        idx = alloc_need(need);
269	    }
270	    if (!load_into(idx, path, file_sz)) {
271	        syslog(LOG_WARNING, "[vmap] vpk load fail cell=%u sz=%u errno=%d",
272	            (unsigned)id, (unsigned)file_sz, errno);
273	        g_blk[idx].id = VMAP_CELL_NONE;
274	        g_blk[idx].refs = 0;
275	        g_blk[idx].file_sz = 0;
276	        coalesce();
277	        return false;
278	    }
279	    g_blk[idx].id = id;
280	    g_blk[idx].file_sz = file_sz;
281	    g_blk[idx].refs = 0;
282	    g_blk[idx].lru = ++g_clock;
283	    *out_idx = idx;
284	    syslog(LOG_NOTICE, "[vmap] vpk ram %u KiB cell=%u",
285	        (unsigned)((file_sz + 1023u) / 1024u), (unsigned)id);
286	    return true;
287	}
288	
289	void vmap_vpk_heap_init(void)
290	{
291	    pthread_mutex_lock(&g_lock);
292	    init_unlocked();
293	    pthread_mutex_unlock(&g_lock);
294	}
295	
296	void vmap_vpk_heap_clear(void)
297	{
298	    pthread_mutex_lock(&g_lock);
299	    if (!g_ready || !g_heap) {
300	        pthread_mutex_unlock(&g_lock);
301	        return;
302	    }
303	    g_n = 1;
304	    g_blk[0].id = VMAP_CELL_NONE;
305	    g_blk[0].off = 0;
306	    g_blk[0].size = (uint32_t)g_heap_bytes;
307	    g_blk[0].file_sz = 0;
308	    g_blk[0].lru = 0;
309	    g_blk[0].refs = 0;
310	    g_clock = 0;
311	    pthread_mutex_unlock(&g_lock);
312	}
313	
314	bool vmap_vpk_heap_pin(vmap_cell_id_t id, const char * path,
315	    const uint8_t ** data, uint32_t * size)
316	{
317	    int idx;
318	
319	    if (!data || !size || id == VMAP_CELL_NONE) {
320	        return false;
321	    }
322	    pthread_mutex_lock(&g_lock);
323	    init_unlocked();
324	    if (!g_ready || !ensure_locked(id, path, &idx)) {
325	        pthread_mutex_unlock(&g_lock);
326	        return false;
327	    }
328	    g_blk[idx].refs++;
329	    *data = g_heap + g_blk[idx].off;
330	    *size = g_blk[idx].file_sz;
331	    pthread_mutex_unlock(&g_lock);
332	    return true;
333	}
334	
335	void vmap_vpk_heap_unpin(vmap_cell_id_t id)
336	{
337	    int idx;
338	
339	    pthread_mutex_lock(&g_lock);
340	    idx = find_id(id);
341	    if (idx >= 0 && g_blk[idx].refs > 0) {
342	        g_blk[idx].refs--;
343	    }
344	    pthread_mutex_unlock(&g_lock);
345	}
346	
347	void vmap_vpk_heap_touch(vmap_cell_id_t id)
348	{
349	    int idx;
350	
351	    pthread_mutex_lock(&g_lock);
352	    idx = find_id(id);
353	    if (idx >= 0) {
354	        g_blk[idx].lru = ++g_clock;
355	    }
356	    pthread_mutex_unlock(&g_lock);
357	}
358	
359	bool vmap_vpk_heap_has(vmap_cell_id_t id)
360	{
361	    bool ok;
362	
363	    pthread_mutex_lock(&g_lock);
364	    init_unlocked();
365	    ok = g_ready && find_id(id) >= 0;
366	    pthread_mutex_unlock(&g_lock);
367	    return ok;
368	}
369	
370	bool vmap_vpk_heap_stats(size_t *arena_bytes, size_t *occupied_bytes,
371	    uint32_t *ncell)
372	{
373	    size_t occupied = 0;
374	    uint32_t cells = 0;
375	    uint32_t i;
376	
377	    pthread_mutex_lock(&g_lock);
378	    if (!g_ready || !g_heap) {
379	        pthread_mutex_unlock(&g_lock);
380	        if (arena_bytes) {
381	            *arena_bytes = VPK_HEAP_BYTES;
382	        }
383	        if (occupied_bytes) {
384	            *occupied_bytes = 0;
385	        }
386	        if (ncell) {
387	            *ncell = 0;
388	        }
389	        return true;
390	    }
391	    for (i = 0; i < g_n; i++) {
392	        if (g_blk[i].id == VMAP_CELL_NONE) {
393	            continue;
394	        }
395	        occupied += g_blk[i].size;
396	        cells++;
397	    }
398	    if (arena_bytes) {
399	        *arena_bytes = g_heap_bytes;
400	    }
401	    if (occupied_bytes) {
402	        *occupied_bytes = occupied;
403	    }
404	    if (ncell) {
405	        *ncell = cells;
406	    }
407	    pthread_mutex_unlock(&g_lock);
408	    return true;
409	}
410	
411	bool vmap_vpk_heap_copy(vmap_cell_id_t id, const char * path,
412	    uint32_t file_off, void * dst, uint32_t len)
413	{
414	    int idx;
415	
416	    if (!dst || len == 0) {
417	        return false;
418	    }
419	    if (id == VMAP_CELL_NONE) {
420	        return file_copy(path, file_off, dst, len);
421	    }
422	    pthread_mutex_lock(&g_lock);
423	    init_unlocked();
424	    if (g_ready && ensure_locked(id, path, &idx)
425	            && file_off + len <= g_blk[idx].file_sz) {
426	        memcpy(dst, g_heap + g_blk[idx].off + file_off, len);
427	        pthread_mutex_unlock(&g_lock);
428	        return true;
429	    }
430	    pthread_mutex_unlock(&g_lock);
431	    return false;
432	}
