32	#ifndef CONFIG_MYVENDOR_VMAP_TILE_CACHE_KB
33	#  define CONFIG_MYVENDOR_VMAP_TILE_CACHE_KB 2048
34	#endif
35	
36	#define VMAP_CACHE_TOTAL_BYTES \
37	    ((size_t)CONFIG_MYVENDOR_VMAP_TILE_CACHE_KB * 1024u)
38	
39	#define VMAP_CACHE_HASH_BUCKETS 4096u
40	#define VMAP_CACHE_MAX_ENTRIES  2048u
41	
42	struct meta_entry {
43	    uint16_t city_id;
44	    uint8_t z;
45	    uint8_t flags;
46	    uint16_t x;
47	    uint16_t y;
48	    uint32_t blob_len;
49	    uint32_t blob_off;
50	    uint32_t lru;
51	    uint32_t hash_next;
52	};
53	
54	struct free_node {
55	    uint32_t off;
56	    uint32_t size;
57	    uint32_t next;
58	};
59	
60	#define VMAP_CACHE_MAX_FREE 64
61	
62	#define VMAP_CACHE_META_BYTES \
63	    (VMAP_CACHE_HASH_BUCKETS * sizeof(uint16_t) + \
64	     VMAP_CACHE_MAX_ENTRIES * sizeof(struct meta_entry))
65	
66	static uint8_t * g_arena;
67	static size_t g_arena_bytes;
68	static uint16_t * g_hash;
69	static struct meta_entry * g_meta;
70	static uint8_t * g_blob_base;
71	static size_t g_blob_cap;
72	static size_t g_blob_high;
73	static uint32_t g_lru_tick;
74	static uint16_t g_city_id;
75	
76	static struct free_node g_free[VMAP_CACHE_MAX_FREE];
77	static uint32_t g_free_head;
78	
79	static uint32_t tile_hash(uint16_t city_id, uint8_t z, int x, int y)
80	{
81	    uint32_t h = (uint32_t)city_id * 2654435761u;
82	    h ^= (uint32_t)z * 2246822519u;
83	    h ^= (uint32_t)(uint16_t)x * 3266489917u;
84	    h ^= (uint32_t)(uint16_t)y * 668265263u;
85	    h ^= h >> 16;
86	    return h % VMAP_CACHE_HASH_BUCKETS;
87	}
88	
89	static struct meta_entry * entry_at(uint32_t idx)
90	{
91	    return &g_meta[idx];
92	}
93	
94	static int entry_alloc_index(void)
95	{
96	    for (uint32_t i = 0; i < VMAP_CACHE_MAX_ENTRIES; i++) {
97	        if ((g_meta[i].flags & VMAP_CACHE_FLAG_USED) == 0) {
98	            return (int)i;
99	        }
100	    }
101	    return -1;
102	}
103	
104	static void hash_unlink(uint32_t bucket, uint32_t idx)
105	{
106	    uint32_t prev = 0;
107	    uint32_t cur = g_hash[bucket];
108	
109	    while (cur != 0) {
110	        uint32_t i = cur - 1;
111	        if (i == idx) {
112	            uint32_t next = g_meta[i].hash_next;
113	            if (prev == 0) {
114	                g_hash[bucket] = next;
115	            } else {
116	                g_meta[prev - 1].hash_next = next;
117	            }
118	            g_meta[i].hash_next = 0;
119	            return;
120	        }
121	        prev = cur;
122	        cur = g_meta[i].hash_next;
123	    }
124	}
125	
126	static void hash_link(uint32_t bucket, uint32_t idx)
127	{
128	    g_meta[idx].hash_next = g_hash[bucket];
129	    g_hash[bucket] = (uint16_t)(idx + 1);
130	}
131	
132	static void free_unlink(uint32_t fi)
133	{
134	    uint32_t prev = 0;
135	    uint32_t cur = g_free_head;
136	
137	    while (cur != 0) {
138	        if (cur - 1 == fi) {
139	            uint32_t next = g_free[fi].next;
140	            if (prev == 0) {
141	                g_free_head = next;
142	            } else {
143	                g_free[prev - 1].next = next;
144	            }
145	            g_free[fi].size = 0;
146	            g_free[fi].next = 0;
147	            return;
148	        }
149	        prev = cur;
150	        cur = g_free[prev - 1].next;
151	    }
152	}
153	
154	static void free_push(uint32_t off, uint32_t size)
155	{
156	    int i;
157	
158	    if (size < 8) {
159	        return;
160	    }
161	
162	    for (i = 0; i < (int)VMAP_CACHE_MAX_FREE; i++) {
163	        if (g_free[i].size == 0) {
164	            continue;
165	        }
166	
167	        if (g_free[i].off + g_free[i].size == off) {
168	            g_free[i].size += size;
169	            off = g_free[i].off;
170	            size = g_free[i].size;
171	            break;
172	        }
173	
174	        if (off + size == g_free[i].off) {
175	            g_free[i].off = off;
176	            g_free[i].size += size;
177	            return;
178	        }
179	    }
180	
181	    for (i = 0; i < (int)VMAP_CACHE_MAX_FREE; i++) {
182	        if (g_free[i].size == 0) {
183	            continue;
184	        }
185	
186	        if (g_free[i].off + g_free[i].size == off) {
187	            g_free[i].size += size;
188	            return;
189	        }
190	
191	        if (off + size == g_free[i].off) {
192	            g_free[i].off = off;
193	            g_free[i].size += size;
194	            return;
195	        }
196	    }
197	
198	    for (i = 0; i < (int)VMAP_CACHE_MAX_FREE; i++) {
199	        if (g_free[i].size == 0) {
200	            g_free[i].off = off;
201	            g_free[i].size = size;
202	            g_free[i].next = g_free_head;
203	            g_free_head = (uint32_t)(i + 1);
204	            return;
205	        }
206	    }
207	
208	    {
209	        int victim = -1;
210	        uint32_t victim_size = UINT32_MAX;
211	
212	        for (i = 0; i < (int)VMAP_CACHE_MAX_FREE; i++) {
213	            if (g_free[i].size == 0) {
214	                continue;
215	            }
216	            if (g_free[i].size < victim_size) {
217	                victim_size = g_free[i].size;
218	                victim = i;
219	            }
220	        }
221	
222	        if (victim >= 0 && size >= victim_size) {
223	            free_unlink((uint32_t)victim);
224	            g_free[victim].off = off;
225	            g_free[victim].size = size;
226	            g_free[victim].next = g_free_head;
227	            g_free_head = (uint32_t)(victim + 1);
228	            BICYCLE_STAB_WARN("vmap arena: free list full, replaced %uB with %uB",
229	                (unsigned)victim_size, (unsigned)size);
230	            bicycle_stab_arena_free_drop();
231	        } else if (victim >= 0) {
232	            BICYCLE_STAB_WARN("vmap arena: free list full, dropped %uB release",
233	                (unsigned)size);
234	            bicycle_stab_arena_free_drop();
235	        }
236	    }
237	}
