239	static int blob_alloc(uint32_t need)
240	{
241	    need = (need + 3u) & ~3u;
242	
243	    uint32_t prev = 0;
244	    uint32_t cur = g_free_head;
245	    while (cur != 0) {
246	        uint32_t fi = cur - 1;
247	        if (g_free[fi].size >= need) {
248	            uint32_t off = g_free[fi].off;
249	            uint32_t rem = g_free[fi].size - need;
250	            if (rem >= 8) {
251	                g_free[fi].off = off + need;
252	                g_free[fi].size = rem;
253	            } else {
254	                uint32_t next = g_free[fi].next;
255	                if (prev == 0) {
256	                    g_free_head = next;
257	                } else {
258	                    g_free[prev - 1].next = next;
259	                }
260	                g_free[fi].size = 0;
261	                g_free[fi].next = 0;
262	            }
263	            return (int)off;
264	        }
265	        prev = cur;
266	        cur = g_free[fi].next;
267	    }
268	
269	    if (g_blob_high + need > g_blob_cap) {
270	        return -1;
271	    }
272	
273	    {
274	        uint32_t off = (uint32_t)g_blob_high;
275	        g_blob_high += need;
276	        return (int)off;
277	    }
278	}
