280	static void entry_release(uint32_t idx)
281	{
282	    struct meta_entry * e = entry_at(idx);
283	    if ((e->flags & VMAP_CACHE_FLAG_USED) == 0) {
284	        return;
285	    }
286	
287	    {
288	        uint32_t bucket = tile_hash(e->city_id, e->z, (int)e->x, (int)e->y);
289	        hash_unlink(bucket, idx);
290	    }
291	
292	    if (e->blob_len > 0) {
293	        free_push(e->blob_off, e->blob_len);
294	    }
295	
296	    memset(e, 0, sizeof(*e));
297	}
