299	static int entry_find_lru(void)
300	{
301	    int victim = -1;
302	    uint32_t best = 0xffffffffu;
303	
304	    for (uint32_t i = 0; i < VMAP_CACHE_MAX_ENTRIES; i++) {
305	        if ((g_meta[i].flags & VMAP_CACHE_FLAG_USED) == 0) {
306	            continue;
307	        }
308	        if (g_meta[i].lru <= best) {
309	            best = g_meta[i].lru;
310	            victim = (int)i;
311	        }
312	    }
313	
314	    return victim;
315	}
