317	static struct meta_entry * entry_lookup(uint16_t city_id, int z, int x, int y)
318	{
319	    uint32_t bucket = tile_hash(city_id, (uint8_t)z, x, y);
320	    uint32_t cur = g_hash[bucket];
321	
322	    while (cur != 0) {
323	        uint32_t i = cur - 1;
324	        struct meta_entry * e = entry_at(i);
325	        if (e->city_id == city_id && e->z == (uint8_t)z &&
326	            e->x == (uint16_t)x && e->y == (uint16_t)y) {
327	            return e;
328	        }
329	        cur = e->hash_next;
330	    }
331	
332	    return NULL;
333	}
