465	static int entry_insert(uint16_t city_id, int z, int x, int y,
466	    const uint8_t * data, uint32_t size, int missing)
467	{
468	    struct meta_entry * existing;
469	    int idx;
470	    int meta_evict_attempts = 0;
471	    struct meta_entry * e;
472	
473	    if (!g_arena) {
474	        if (vmap_cache_arena_init() != 0) {
475	            return -1;
476	        }
477	    }
478	
479	    existing = entry_lookup(city_id, z, x, y);
480	    if (existing) {
481	        uint32_t eidx = (uint32_t)(existing - g_meta);
482	        entry_release(eidx);
483	    }
484	
485	    idx = entry_alloc_index();
486	    while (idx < 0) {
487	        if (++meta_evict_attempts > (int)VMAP_CACHE_MAX_ENTRIES) {
488	            BICYCLE_STAB_WARN("vmap arena: meta slot evict cap");
489	            bicycle_stab_arena_evict_cap();
490	            return -1;
491	        }
492	        {
493	            int victim = entry_find_lru();
494	            if (victim < 0) {
495	                return -1;
496	            }
497	            entry_release((uint32_t)victim);
498	        }
499	        idx = entry_alloc_index();
500	    }
501	
502	    e = entry_at((uint32_t)idx);
503	    e->city_id = city_id;
504	    e->z = (uint8_t)z;
505	    e->x = (uint16_t)x;
506	    e->y = (uint16_t)y;
507	    e->flags = VMAP_CACHE_FLAG_USED;
508	    e->lru = ++g_lru_tick;
509	
510	    if (missing) {
511	        e->flags |= VMAP_CACHE_FLAG_MISSING;
512	        e->blob_len = 0;
513	        e->blob_off = 0;
514	    } else {
515	        uint32_t need = ((uint32_t)size + 3u) & ~3u;
516	        int off = -1;
517	        int evict_attempts = 0;
518	
519	        while (off < 0) {
520	            off = blob_alloc(need);
521	            if (off >= 0) {
522	                break;
523	            }
524	            if (++evict_attempts > (int)VMAP_CACHE_MAX_ENTRIES) {
525	                BICYCLE_STAB_WARN(
526	                    "vmap arena: blob evict cap z=%d (%d,%d) need=%u high=%u cap=%u",
527	                    z, x, y, (unsigned)need, (unsigned)g_blob_high,
528	                    (unsigned)g_blob_cap);
529	                bicycle_stab_arena_evict_cap();
530	                memset(e, 0, sizeof(*e));
531	                return -1;
532	            }
533	            {
534	                int victim = entry_find_lru();
535	                if (victim < 0) {
536	                    memset(e, 0, sizeof(*e));
537	                    return -1;
538	                }
539	                entry_release((uint32_t)victim);
540	            }
541	        }
542	
543	        memcpy(g_blob_base + off, data, size);
544	        e->blob_off = (uint32_t)off;
545	        e->blob_len = size;
546	    }
547	
548	    hash_link(tile_hash(city_id, (uint8_t)z, x, y), (uint32_t)idx);
549	    return 0;
550	}
