2947	            s_road_refs[n++].rec = rec;
2948	        }
2949	        if (n == s_road_ref_cap && scan.remaining > 0) {
2950	            overflow = true;
2951	        }
2952	
2953	        if (!overflow) {
2954	            s_road_sorted = sorted && n > 0;
2955	            if (n > 0) {
2956	                s_road_cls_end[prev] = (uint16_t)n;
2957	            }
2958	
2959	            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2960	                if (!vmap_style_road_visible((uint8_t)cls, scale)) {
2961	                    continue;
2962	                }
2963	                /* 壳 → 芯 成对；path 的壳在 road_stroke_feature() 里直接跳过。 */
2964	                if (s_road_sorted) {
2965	                    const int start = s_road_cls_start[cls];
2966	                    const int end = s_road_cls_end[cls];
2967	
2968	                    if (start >= end) {
2969	                        continue;
2970	                    }
2971	                    road_stroke_refs_range(c, s_road_refs, start, end, layer_end,
2972	                        cls, true, base_x, base_y, u, extent, ws_q8, scratch,
2973	                        scratch_cap);
2974	#if VMAP_JUNCTION_FILL
2975	                    if (cls <= VMAP_ROAD_TERTIARY) {
2976	                        road_junction_begin();
2977	                    }
2978	#endif
2979	                    road_stroke_refs_range(c, s_road_refs, start, end, layer_end,
2980	                        cls, false, base_x, base_y, u, extent, ws_q8, scratch,
2981	                        scratch_cap);
2982	                } else {
2983	                    /* 旧瓦片（未按 class 排序）：退回逐 class 全量过滤。 */
2984	                    road_stroke_refs(c, s_road_refs, n, layer_end, cls, true,
2985	                        base_x, base_y, u, extent, ws_q8, scratch, scratch_cap);
2986	#if VMAP_JUNCTION_FILL
2987	                    if (cls <= VMAP_ROAD_TERTIARY) {
2988	                        road_junction_begin();
2989	                    }
2990	#endif
2991	                    road_stroke_refs(c, s_road_refs, n, layer_end, cls, false,
2992	                        base_x, base_y, u, extent, ws_q8, scratch, scratch_cap);
2993	                }
2994	#if VMAP_JUNCTION_FILL
2995	                if (cls <= VMAP_ROAD_TERTIARY) {
2996	                    road_junction_flush(c, cls, ws_q8);
2997	                }
2998	#endif
2999	            }
3000	            return;
3001	        }
3002	    }
3003	
3004	    /* 回退：未绑定索引、cap<=0 或索引溢出时走原实现（逐 class 全层扫描）。 */
3005	    for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
3006	        if (!vmap_style_road_visible((uint8_t)cls, scale)) {
3007	            continue;
3008	        }
3009	        road_stroke_scan(c, tile, cls, true, base_x, base_y, u, extent, ws_q8,
3010	            scratch, scratch_cap);
3011	#if VMAP_JUNCTION_FILL
3012	        if (cls <= VMAP_ROAD_TERTIARY) {
3013	            road_junction_begin();
3014	        }
3015	#endif
3016	        road_stroke_scan(c, tile, cls, false, base_x, base_y, u, extent, ws_q8,
3017	            scratch, scratch_cap);
3018	#if VMAP_JUNCTION_FILL
3019	        if (cls <= VMAP_ROAD_TERTIARY) {
3020	            road_junction_flush(c, cls, ws_q8);
