3045	/**
3046	 * @brief 用纯色清画布。
3047	 * @param c 画布。
3048	 * @param color RGB565。
3049	 */
3050	void vmap_render_clear(vmap_canvas_t * c, uint16_t color)
3051	{
3052	    vmap_blit_surface_t surf;
3053	
3054	    if (!c || !c->buf) {
3055	        return;
3056	    }
3057	
3058	    /* 先问搬运后端（走 EPIC 时是一整块矩形一条命令）；它不可用或没通过自检
3059	     * 时，同一个调用会把 CPU 版本做完 —— 见 vmap_blit.h。 */
3060	    render_surface(c, &surf);
3061	    vmap_blit_fill(render_blit(), &surf, 0, 0, c->w, c->h, color);
3062	}
3063	
3064	/*
3065	 * 这里原有一个 `render_fill_span(row, x0, x1, color)`（成对写的一行填充）。
3066	 * scroll 改成"矩形 + 两条边"之后它没有调用者了 —— 补边现在走
3067	 * `vmap_blit_fill()`，CPU 那支的成对写等价物在 `vmap_blit.c` 的 `cpu_fill()`。
3068	 */
3069	
3070	void vmap_render_scroll(vmap_canvas_t * c, int32_t dx, int32_t dy, uint16_t fill)
3071	{
3072	    vmap_blit_surface_t surf;
3073	    vmap_blit_t * blit;
3074	    int32_t copy_w;
3075	    int32_t copy_h;
3076	    int32_t x0;
3077	    int32_t y0;
3078	
3079	    if (!c || !c->buf) {
3080	        return;
3081	    }
3082	
3083	    if (dx == 0 && dy == 0) {
3084	        return;
3085	    }
3086	
3087	    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
3088	        vmap_render_clear(c, fill);
3089	        return;
3090	    }
3091	
3092	    /*
3093	     * 原来这条是逐行 memmove + 逐行补边；现在拆成**一块矩形 + 两条边**，
3094	     * 这样整块矩形才有机会落到 EPIC 上（一条命令 vs 472 次函数调用）。
3095	     * 逐行版的代价是实打实的：使用过程一帧的 `cyc_begin` 里 92% 就是它
3096	     * （见 `[vperf] frame ... scr=`），单帧 164 ms。
3097	     *
3098	     * 语义与逐行版逐位相同：
3099	     *   拷贝区 = 目的 (x0,y0) ← 源 (x0+dx, y0+dy)，尺寸 (w−|dx|, h−|dy|)；
3100	     *   横向露出的 |dx| 列只覆盖**拷贝区那几行**，纵向露出的 |dy| 行整宽铺满。
3101	     * 次序必须是**先拷贝后填充**：露出的边落在源矩形的范围内（横向边在
3102	     * y 属于拷贝区时、纵向边在 x 属于拷贝区时），先填会把还没读的源像素盖掉。
3103	     * 逐行版之所以没这个问题，是因为它在同一行里也是先 memmove 后补边、
3104	     * 且行的方向按 dy 的符号选过（跨行的重叠只有那个方向是安全的）。
3105	     */
3106	    copy_w = c->w - (dx >= 0 ? dx : -dx);
3107	    copy_h = c->h - (dy >= 0 ? dy : -dy);
3108	    x0 = (dx > 0) ? 0 : -dx;
3109	    y0 = (dy > 0) ? 0 : -dy;
3110	
3111	    render_surface(c, &surf);
3112	    blit = render_blit();
3113	
3114	    (void)vmap_blit_copy(blit, &surf, x0, y0, &surf, x0 + dx, y0 + dy,
3115	        copy_w, copy_h);
3116	
3117	    if (dx > 0) {
3118	        (void)vmap_blit_fill(blit, &surf, c->w - dx, y0, dx, copy_h, fill);
3119	    } else if (dx < 0) {
3120	        (void)vmap_blit_fill(blit, &surf, 0, y0, -dx, copy_h, fill);
3121	    }
3122	
3123	    if (dy > 0) {
3124	        (void)vmap_blit_fill(blit, &surf, 0, c->h - dy, c->w, dy, fill);
3125	    } else if (dy < 0) {
3126	        (void)vmap_blit_fill(blit, &surf, 0, 0, c->w, -dy, fill);
3127	    }
3128	}
