3130	static void fill_rect(vmap_canvas_t * c, int32_t x1, int32_t y1, int32_t x2,
3131	    int32_t y2, uint16_t color)
3132	{
3133	    int32_t y;
3134	
3135	    if (!c || x1 >= x2 || y1 >= y2) {
3136	        return;
3137	    }
3138	    if (x1 < 0) {
3139	        x1 = 0;
3140	    }
3141	    if (y1 < 0) {
3142	        y1 = 0;
3143	    }
3144	    if (x2 > c->w) {
3145	        x2 = c->w;
3146	    }
3147	    if (y2 > c->h) {
3148	        y2 = c->h;
3149	    }
3150	    if (x1 >= x2 || y1 >= y2) {
3151	        return;
3152	    }
3153	
3154	    for (y = y1; y < y2; y++) {
3155	        blend_span(c, x1, x2 - 1, y, color);
3156	    }
3157	}
