3159	/**
3160	 * @brief 将瓦片绘制到画布。
3161	 */
3162	void vmap_render_draw_tile(vmap_canvas_t * c, const vmap_tile_t * tile,
3163	    float base_x, float base_y, float scale, vmap_point_t * scratch, int scratch_cap)
3164	{
3165	    const vmap_style_t * style;
3166	    int32_t x1;
3167	    int32_t y1;
3168	    int32_t x2;
3169	    int32_t y2;
3170	
3171	    if (!c || !tile) {
3172	        return;
3173	    }
3174	
3175	    /* Vector layers do not cover every pixel. Track/route ribbons are stamped
3176	     * on top; without a bg fill, restamping leaves those pixels behind.
3177	     *
3178	     * 整块矩形（无脏区裁剪）交给搬运后端：EPIC 一条命令写完，CPU 逐行
3179	     * `blend_span` 的 8.2M 周期/帧（4 张瓦片、235k px）降到约 3.6M；后端不可用
3180	     * 时 `vmap_blit_fill()` 自己退回 CPU 版本，像素与 `fill_rect()` 相同
3181	     * （开机 `[vblit] fill dif=0` 自检）。有脏区裁剪时必须走 `fill_rect()`：
3182	     * 裁剪是逐行多段判定，搬运器只认矩形。 */
3183	    x1 = (int32_t)floorf(base_x);
3184	    y1 = (int32_t)floorf(base_y);
3185	    x2 = (int32_t)ceilf(base_x + 256.0f * scale);
3186	    y2 = (int32_t)ceilf(base_y + 256.0f * scale);
3187	    if (c->clip_n == 0u) {
3188	        vmap_blit_surface_t surf;
3189	
3190	        render_surface(c, &surf);
3191	        vmap_blit_fill(render_blit(), &surf, x1, y1, x2 - x1, y2 - y1,
3192	            vmap_style_bg565());
3193	    } else {
3194	        fill_rect(c, x1, y1, x2, y2, vmap_style_bg565());
3195	    }
3196	
3197	    style = vmap_style_current();
3198	    uint16_t extent = vmap_tile_extent(tile);
3199	    const uint16_t forest = RGB565(style->forest_r, style->forest_g,
3200	        style->forest_b);
3201	    const uint16_t water = RGB565(style->water_r, style->water_g, style->water_b);
3202	
3203	    draw_land_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_LAND), extent,
3204	        base_x, base_y, scale, scratch, scratch_cap);
3205	    draw_poly_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_FOREST), extent,
3206	        base_x, base_y, scale, forest, 0, 0, scratch, scratch_cap);
3207	    draw_poly_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_WATER), extent,
3208	        base_x, base_y, scale, water, 0, 0, scratch, scratch_cap);
3209	    draw_line_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_WATERWAY), extent,
3210	        base_x, base_y, scale, scratch, scratch_cap);
3211	    draw_road_layer(c, tile, extent, base_x, base_y, scale, scratch, scratch_cap);
3212	}

