2401	static void draw_land_layer(vmap_canvas_t * c, vmap_feature_iter_t it,
2402	    uint16_t extent, float base_x, float base_y, float scale,
2403	    vmap_point_t * scratch, int scratch_cap)
2404	{
2405	    const vmap_style_t * style = vmap_style_current();
2406	    float u = 256.0f * scale / (float)extent;
2407	    vmap_feature_t f;
2408	
2409	    while (vmap_feature_iter_next(&it, &f)) {
2410	        int32_t n;
2411	        int32_t i;
2412	
2413	        /* STYLE.md §5.4：商务/工业 z15 起（设备 z14 ⇒ 不画），住/校/园 z12.5 起。 */
2414	        if (!vmap_style_land_visible(f.attr, scale)) {
2415	            continue;
2416	        }
2417	        if (!vmap_feature_is_closed(&f) || f.point_count < 3) {
2418	            continue;
2419	        }
2420	        n = f.point_count;
2421	        if (n > scratch_cap) {
2422	            n = scratch_cap;
2423	        }
2424	        {
2425	            /* 顺带算包围盒（不额外投影），完全写不到就整条跳过 fill_polygon。 */
2426	            int32_t bx1 = 0;
2427	            int32_t by1 = 0;
2428	            int32_t bx2 = 0;
2429	            int32_t by2 = 0;
2430	
2431	            for (i = 0; i < n; i++) {
2432	                int32_t x = (int32_t)(base_x + vmap_feature_x(&f, (uint16_t)i) * u);
2433	                int32_t y = (int32_t)(base_y + vmap_feature_y(&f, (uint16_t)i) * u);
2434	
2435	                scratch[i].x = x;
2436	                scratch[i].y = y;
2437	                if (i == 0) {
2438	                    bx1 = bx2 = x;
2439	                    by1 = by2 = y;
2440	                } else {
2441	                    if (x < bx1) { bx1 = x; }
2442	                    if (x > bx2) { bx2 = x; }
2443	                    if (y < by1) { by1 = y; }
2444	                    if (y > by2) { by2 = y; }
2445	                }
2446	            }
2447	            if (!box_may_write(c, bx1 - 2, by1 - 2, bx2 + 2, by2 + 2)) {
2448	                continue;
2449	            }
2450	        }
2451	        fill_polygon(c, scratch, n, land_fill_color(style, f.attr));
2452	    }
2453	}
