2455	static void draw_poly_layer(vmap_canvas_t * c, vmap_feature_iter_t it,
2456	    uint16_t extent, float base_x, float base_y, float scale, uint16_t fill_color,
2457	    uint16_t stroke_color, int32_t stroke_w, vmap_point_t * scratch, int scratch_cap)
2458	{
2459	    float u = 256.0f * scale / (float)extent;
2460	    vmap_feature_t f;
2461	
2462	    while (vmap_feature_iter_next(&it, &f)) {
2463	        int32_t n;
2464	        int32_t i;
2465	
2466	        if (!vmap_feature_is_closed(&f) || f.point_count < 3) {
2467	            continue;
2468	        }
2469	        n = f.point_count;
2470	        if (n > scratch_cap) {
2471	            n = scratch_cap;
2472	        }
2473	        {
2474	            /* 顺带算包围盒（不额外投影）；填充与描边共用同一道闸门，取较大的外扩量
2475	             * （描边半宽 + AA 余量）—— 宁可多画。 */
2476	            const int32_t pad = (stroke_w > 0 ? (stroke_w + 1) / 2 : 0) + 2;
2477	            int32_t bx1 = 0;
2478	            int32_t by1 = 0;
2479	            int32_t bx2 = 0;
2480	            int32_t by2 = 0;
2481	
2482	            for (i = 0; i < n; i++) {
2483	                int32_t x = (int32_t)(base_x + vmap_feature_x(&f, (uint16_t)i) * u);
2484	                int32_t y = (int32_t)(base_y + vmap_feature_y(&f, (uint16_t)i) * u);
2485	
2486	                scratch[i].x = x;
2487	                scratch[i].y = y;
2488	                if (i == 0) {
2489	                    bx1 = bx2 = x;
2490	                    by1 = by2 = y;
2491	                } else {
2492	                    if (x < bx1) { bx1 = x; }
2493	                    if (x > bx2) { bx2 = x; }
2494	                    if (y < by1) { by1 = y; }
2495	                    if (y > by2) { by2 = y; }
2496	                }
2497	            }
2498	            if (!box_may_write(c, bx1 - pad, by1 - pad, bx2 + pad, by2 + pad)) {
2499	                continue;
2500	            }
2501	        }
2502	        fill_polygon(c, scratch, n, fill_color);
2503	        if (stroke_w > 0) {
2504	            stroke_polygon(c, scratch, n, stroke_w, stroke_color);
2505	        }
2506	    }
2507	}
