2509	/* ── 路口楔形补芯（WP-FIX3 ①）─────────────────────────────────────────────
2510	 *
2511	 * 现象：同一等级的两条路在共享顶点处相遇时，两条路各带 1px 壳；在两条芯之间
2512	 * 的锐角楔形里，两条壳贴在一起，形成一条贯穿路口的 V 形深色缝（12× 裁切下
2513	 * 一眼可见，1× 下让路口像两个带框色块拼起来）。
2514	 *
2515	 * 为什么"同 class 先壳后芯"不够：两遍 pass 只能让后画的芯盖住先画的壳；两条
2516	 * 路的芯在共享顶点处只是**相切**、并不重叠，壳仍然从楔形里露出来。所以这里
2517	 * 在每级芯画完之后，把同 class、不同要素、相距 <= 3px 的顶点对找出来，用
2518	 * 两条芯的边围成的三角形填上芯色：路口中心变成一块连续路面，壳只留在路网
2519	 * 外缘。
2520	 *
2521	 * 只在 class 1..4（motorway..tertiary）做；顶点表满 256 条就整级跳过（宁可
2522	 * 少补，不影响正确性）。关掉：VMAP_JUNCTION_FILL 置 0。
2523	 */
2524	#define VMAP_JUNCTION_FILL 1
2525	
2526	#if VMAP_JUNCTION_FILL
2527	#define VMAP_JUNC_CAP      256
2528	#define VMAP_JUNC_BUCKETS  256
2529	#define VMAP_JUNC_MAX_D2   9        /* 3px */
2530	#define VMAP_JUNC_L_MIN    4
2531	#define VMAP_JUNC_L_MAX    12
2532	
2533	typedef struct {
2534	    int16_t x;
2535	    int16_t y;
2536	    int16_t dx;                 /* 单位方向 ×256：从顶点指向本路体内 */
2537	    int16_t dy;
2538	    int16_t hw;                 /* 芯半宽 px */
2539	    int16_t next;               /* 同桶下一条 */
2540	    const uint16_t * feat;      /* 要素身份（coords 指针） */
2541	} vmap_junc_pt_t;
2542	
2543	static vmap_junc_pt_t s_junc[VMAP_JUNC_CAP];
2544	static int16_t s_junc_head[VMAP_JUNC_BUCKETS];
2545	static int s_junc_n;
2546	static bool s_junc_overflow;
2547	
2548	/** 8px 网格哈希（顶点对只可能落在同一/相邻格）。 */
2549	static int junc_bucket(int32_t x, int32_t y)
2550	{
2551	    const uint32_t cx = (uint32_t)(x + 4096) >> 3;
2552	    const uint32_t cy = (uint32_t)(y + 4096) >> 3;
2553	
2554	    return (int)((cx * 37u + cy) & (VMAP_JUNC_BUCKETS - 1));
2555	}

2756	static bool road_end_clipped(const vmap_feature_t * f, int32_t i, uint16_t extent)
2757	{
2758	    const int32_t x = vmap_feature_x(f, (uint16_t)i);
