1986	    float min_seg_px, float max_dev_px)
1987	{
1988	    const double min_seg2 = (double)min_seg_px * (double)min_seg_px;
1989	    const double max_dev2 = (double)max_dev_px * (double)max_dev_px;
1990	    int32_t w;
1991	
1992	    if (n < 3) {
1993	        return n;
1994	    }
1995	
1996	    w = 1;
1997	    for (int32_t i = 1; i < n - 1; i++) {
1998	        const double dev2 = pt_seg_dist2((double)pts[w - 1].x, (double)pts[w - 1].y,
1999	            (double)pts[i].x, (double)pts[i].y,
2000	            (double)pts[i + 1].x, (double)pts[i + 1].y);
2001	        const double dx = (double)pts[i].x - (double)pts[w - 1].x;
2002	        const double dy = (double)pts[i].y - (double)pts[w - 1].y;
2003	        const double seg2 = dx * dx + dy * dy;
2004	
2005	        if (dev2 < max_dev2) {
2006	            continue;
2007	        }
2008	
2009	        if (seg2 < min_seg2) {
2010	            pts[w - 1] = pts[i];
2011	        } else {
2012	            pts[w++] = pts[i];
2013	        }
2014	    }
2015	
2016	    {
2017	        const double dx = (double)pts[n - 1].x - (double)pts[w - 1].x;
2018	        const double dy = (double)pts[n - 1].y - (double)pts[w - 1].y;
2019	
2020	        if (dx * dx + dy * dy < min_seg2 && w >= 2) {
2021	            pts[w - 1] = pts[n - 1];
2022	        } else {
2023	            pts[w++] = pts[n - 1];
2024	        }
2025	    }
2026	
2027	    return w;
2028	}
