2038	/**
2039	 * Skip area:highway leftovers: a closed ring whose interior is much wider
2040	 * than a schematic stroke (roundabouts stay — they are compact).
2041	 */
2042	static bool road_ring_is_area(const vmap_point_t * pts, int32_t n)
2043	{
2044	    int32_t i;
2045	    int32_t dx;
2046	    int32_t dy;
2047	    double area2;
2048	    double peri;
2049	    double compactness;
2050	    double mean_w;
2051	
2052	    if (!pts || n < 5) {
2053	        return false;
2054	    }
2055	
2056	    dx = pts[0].x - pts[n - 1].x;
2057	    dy = pts[0].y - pts[n - 1].y;
2058	    if (dx * dx + dy * dy > 16) {
2059	        return false;
2060	    }
2061	
2062	    area2 = 0.0;
2063	    peri = 0.0;
2064	    for (i = 0; i < n - 1; i++) {
2065	        area2 += (double)pts[i].x * (double)pts[i + 1].y
2066	            - (double)pts[i + 1].x * (double)pts[i].y;
2067	        peri += hypot((double)(pts[i + 1].x - pts[i].x),
2068	            (double)(pts[i + 1].y - pts[i].y));
2069	    }
2070	
2071	    area2 = fabs(area2);
2072	    if (peri < 8.0) {
2073	        return false;
2074	    }
2075	
2076	    compactness = (2.0 * M_PI * area2) / (peri * peri);
2077	    mean_w = area2 / peri;
2078	    if (compactness > 0.55) {
2079	        return false;
2080	    }
2081	
2082	    return mean_w > 10.0 && compactness < 0.45;
2083	}
